      // 3. Confirm with real server ID
      confirmMessage(tempId, {
        id, // Replace temp ID with server ID
        status: 'sent',
      })
    } catch (error) {
      // 4. Mark as failed (but keep visible!)
      failMessage(tempId, {
        status: 'failed',
