## Implementing Contextual Loading States

Here's how to build a loading system that actually communicates:

```tsx
// Import icons from lucide-react, heroicons, or your preferred icon library
// npm install lucide-react
import { Wifi as WifiIcon, Cpu as CpuIcon, Pencil as PencilIcon } from 'lucide-react'

type LoadingPhase = 'idle' | 'connecting' | 'processing' | 'generating' | 'complete'

interface LoadingStateProps {
  phase: LoadingPhase
  tokens?: number
  estimatedTokens?: number
  onCancel?: () => void
}

function LoadingState({ phase, tokens, estimatedTokens, onCancel }: LoadingStateProps) {
  // Nothing to show when idle or complete
  if (phase === 'idle' || phase === 'complete') return null

  const config = {
    connecting: {
      icon: <WifiIcon className="w-4 h-4" />,
      message: 'Connecting to AI...',
      showCancel: false,
    },
    processing: {
      icon: <CpuIcon className="w-4 h-4" />,
      message: 'Understanding your question...',
      showCancel: true,
    },
    generating: {
      icon: <PencilIcon className="w-4 h-4" />,
      message: 'Writing response...',
      showCancel: true,
    },
  }[phase]

  return (
    <div className="flex items-center justify-between p-3 bg-blue-50 rounded-lg">
      <div className="flex items-center gap-3">
        <div className="p-2 bg-blue-100 rounded-full animate-pulse">{config.icon}</div>
        <div>
          <p className="text-sm font-medium text-blue-900">{config.message}</p>
          {phase === 'generating' && tokens !== undefined && (
            <p className="text-xs text-blue-600">
              {tokens} tokens
              {estimatedTokens && ` / ~${estimatedTokens}`}
            </p>
          )}
        </div>
      </div>

      {config.showCancel && onCancel && (
        <button onClick={onCancel} className="text-sm text-blue-600 hover:text-blue-800">
          Cancel
        </button>
      )}
    </div>
  )
}
```

Now use it in your chat component:

```tsx
import { useState, useRef } from 'react'

// Simple token estimation: ~4 characters per token on average
function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4)
}

// Simple message list component
function MessageList({ messages }: { messages: string[] }) {
  return (
    <div className="flex flex-col gap-2">
      {messages.map((msg, i) => (
        <div key={i}>{msg}</div>
      ))}
    </div>
  )
}

// Simple chat input component
function ChatInput({ onSend }: { onSend: (content: string) => void }) {
  const [input, setInput] = useState('')
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault()
        onSend(input)
        setInput('')
      }}
    >
      <input value={input} onChange={(e) => setInput(e.target.value)} />
      <button type="submit">Send</button>
    </form>
  )
}

function Chat() {
  const [phase, setPhase] = useState<LoadingPhase>('idle')
  const [tokens, setTokens] = useState(0)
  const [messages, setMessages] = useState<string[]>([])
  const [currentMessage, setCurrentMessage] = useState('')
  const abortControllerRef = useRef<AbortController | null>(null)

  // Helper to append text to the current streaming message
  const appendToMessage = (chunk: string) => {
    setCurrentMessage((prev) => prev + chunk)
  }

  const sendMessage = async (content: string) => {
    setPhase('connecting')
    setCurrentMessage('')
    abortControllerRef.current = new AbortController()

    const response = await fetch('/api/chat', {
      method: 'POST',
      body: JSON.stringify({ message: content }),
      signal: abortControllerRef.current.signal,
    })

    setPhase('processing')

    const reader = response.body?.getReader()
    if (!reader) return

    setPhase('generating')

    while (true) {
      const { done, value } = await reader.read()
      if (done) break

      const chunk = new TextDecoder().decode(value)
      setTokens((prev) => prev + estimateTokens(chunk))
      appendToMessage(chunk)
    }

    // Finalize the message
    setMessages((prev) => [...prev, currentMessage])
    setPhase('complete')
  }

  return (
    <div>
      <MessageList messages={messages} />
      <LoadingState
        phase={phase}
        tokens={tokens}
        estimatedTokens={500}
        onCancel={() => abortControllerRef.current?.abort()}
      />
      <ChatInput onSend={sendMessage} />
    </div>
  )
}
```

