## Multi-Stage Indicators

Basic typing indicators show one state: "thinking." But AI processing often has multiple phases, and
showing them resets user patience at each transition.

**Single stage:**

- "Thinking..." (0s)
- ...still "Thinking..." (5s)
- ...still "Thinking..." (10s) — user gets frustrated

**Multiple stages:**

- "Reading your message..." (0s)
- "Thinking..." (2s) — patience reset
- "Writing response..." (4s) — patience reset
- First words appear (6s)

Same 6-second wait, very different perception. Each stage change signals progress.

Here's how to implement it:

```tsx
import { useState, useCallback, useRef } from 'react'
// Import icons from lucide-react, heroicons, or your preferred icon library
// npm install lucide-react
import { Eye as EyeIcon, Sparkles as SparklesIcon, Pencil as PencilIcon } from 'lucide-react'

type Stage = {
  id: string
  label: string
  icon: React.ReactNode
  duration: number
}

const defaultStages: Stage[] = [
  {
    id: 'reading',
    label: 'Reading your message...',
    icon: <EyeIcon className="w-4 h-4" />,
    duration: 1000,
  },
  {
    id: 'thinking',
    label: 'Thinking...',
    icon: <SparklesIcon className="w-4 h-4" />,
    duration: 2000,
  },
  {
    id: 'writing',
    label: 'Writing response...',
    icon: <PencilIcon className="w-4 h-4" />,
    duration: 1500,
  },
]

function useMultiStageTyping(stages: Stage[] = defaultStages) {
  const [currentStageIndex, setCurrentStageIndex] = useState(-1)
  const [isActive, setIsActive] = useState(false)
  const timeoutRef = useRef<NodeJS.Timeout>()

  const start = useCallback(() => {
    setIsActive(true)
    setCurrentStageIndex(0)

    let index = 0
    const advanceStage = () => {
      index++
      if (index < stages.length) {
        setCurrentStageIndex(index)
        timeoutRef.current = setTimeout(advanceStage, stages[index].duration)
      }
      // Stay on last stage until stopped
    }

    timeoutRef.current = setTimeout(advanceStage, stages[0].duration)
  }, [stages])

  const stop = useCallback(() => {
    setIsActive(false)
    setCurrentStageIndex(-1)
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current)
    }
  }, [])

  const currentStage = currentStageIndex >= 0 ? stages[currentStageIndex] : null

  return { isActive, currentStage, start, stop }
}
```

