      e.preventDefault()
      handleSend()
    }
    // Enter without modifier on desktop sends
    // But on mobile, Enter should add newline (let user tap send button)
    if (e.key === 'Enter' && !e.shiftKey && !isMobile()) {
      e.preventDefault()
      handleSend()
    }
