## Full Implementation

Here's a complete error recovery system for chat:

```typescript
type ErrorType = 'rateLimit' | 'timeout' | 'network' | 'server' | 'auth' | 'unknown'

interface ErrorRecoveryState {
  error: Error | null
  errorType: ErrorType | null
  attemptNumber: number
  maxAttempts: number
  retryIn: number | null
  isRetrying: boolean
  canRetry: boolean
}

interface ErrorRecoveryConfig {
  maxRetries?: number
  initialDelay?: number
  maxDelay?: number
  onRetryAttempt?: (attempt: number) => void
  onSuccess?: (attempt: number) => void
  onMaxRetriesReached?: (error: Error) => void
}

function useErrorRecovery(config: ErrorRecoveryConfig = {}) {
  const {
    maxRetries = 3,
    initialDelay = 1000,
    maxDelay = 30000,
    onRetryAttempt,
    onSuccess,
    onMaxRetriesReached,
  } = config

  const [state, setState] = useState<ErrorRecoveryState>({
    error: null,
    errorType: null,
    attemptNumber: 0,
    maxAttempts: maxRetries,
    retryIn: null,
    isRetrying: false,
    canRetry: false,
  })

  const countdownRef = useRef<NodeJS.Timeout>()

  const classifyError = (error: unknown): ErrorType => {
    if (error instanceof Response) {
      if (error.status === 429) return 'rateLimit'
      if (error.status === 401 || error.status === 403) return 'auth'
      if (error.status >= 500) return 'server'
    }

    if (error instanceof TypeError && error.message === 'Failed to fetch') {
      return 'network'
    }

    if (error instanceof DOMException && error.name === 'AbortError') {
      return 'timeout'
    }

    return 'unknown'
  }

  const getRetryDelay = (errorType: ErrorType, attempt: number, response?: Response): number => {
    // Rate limit: respect Retry-After header
    if (errorType === 'rateLimit' && response?.headers.get('Retry-After')) {
      const retryAfter = parseInt(response.headers.get('Retry-After')!)
      return retryAfter * 1000
    }

    // Exponential backoff with jitter
    const baseDelay = initialDelay * Math.pow(2, attempt)
    const jitter = Math.random() * 0.3 * baseDelay // 0-30% jitter
    return Math.min(baseDelay + jitter, maxDelay)
  }

  const shouldRetry = (errorType: ErrorType): boolean => {
    // Never retry auth errors—user action required
    if (errorType === 'auth') return false

    // Everything else is potentially retryable
    return true
  }

  const execute = async <T>(fn: () => Promise<T>): Promise<T> => {
    let attempt = 0

    while (true) {
      try {
        setState((prev) => ({
          ...prev,
          isRetrying: attempt > 0,
          attemptNumber: attempt,
        }))

        const result = await fn()

        // Success!
        setState({
          error: null,
          errorType: null,
          attemptNumber: attempt,
          maxAttempts: maxRetries,
          retryIn: null,
          isRetrying: false,
          canRetry: false,
        })

        if (attempt > 0) {
          onSuccess?.(attempt)
        }

        return result
      } catch (error) {
        const errorType = classifyError(error)

        // Can we retry?
        if (!shouldRetry(errorType) || attempt >= maxRetries) {
          setState({
            error: error as Error,
            errorType,
            attemptNumber: attempt,
            maxAttempts: maxRetries,
            retryIn: null,
            isRetrying: false,
            canRetry: shouldRetry(errorType) && attempt < maxRetries,
          })

          if (attempt >= maxRetries) {
            onMaxRetriesReached?.(error as Error)
          }

          throw error
        }

        // Calculate delay
        const delay = getRetryDelay(errorType, attempt, error as Response)

        // Update state with countdown
        setState({
          error: error as Error,
          errorType,
          attemptNumber: attempt,
          maxAttempts: maxRetries,
          retryIn: delay,
          isRetrying: false,
          canRetry: true,
        })

        // Start countdown
        let remaining = delay
        const countdownInterval = setInterval(() => {
          remaining -= 1000
          setState((prev) => ({ ...prev, retryIn: Math.max(0, remaining) }))
        }, 1000)

        // Wait
        await sleep(delay)

        clearInterval(countdownInterval)
        onRetryAttempt?.(attempt + 1)
        attempt++
      }
    }
  }

  const reset = () => {
    if (countdownRef.current) {
      clearTimeout(countdownRef.current)
    }
    setState({
      error: null,
      errorType: null,
      attemptNumber: 0,
      maxAttempts: maxRetries,
      retryIn: null,
      isRetrying: false,
      canRetry: false,
    })
  }

  return {
    ...state,
    execute,
    reset,
  }
}
```

