Put it all together in your chat:

```tsx
function ResilientChat() {
  const [messages, setMessages] = useState<Message[]>([])
  const [pendingMessage, setPendingMessage] = useState<string | null>(null)

  const { error, errorType, attemptNumber, maxAttempts, retryIn, execute, reset } =
    useErrorRecovery({
      maxRetries: 3,
      onSuccess: (attempt) => {
        if (attempt > 0) {
          console.log(`Succeeded after ${attempt + 1} attempts`)
        }
      },
      onMaxRetriesReached: () => {
        // Keep the failed message visible for manual retry
      },
    })

  const sendMessage = async (content: string) => {
    // Save message immediately (optimistic UI)
    setPendingMessage(content)
    setMessages((prev) => [
      ...prev,
      {
        id: `temp-${Date.now()}`,
        role: 'user',
        content,
        status: 'sending',
      },
    ])

    try {
      await execute(async () => {
        const response = await fetch('/api/chat', {
          method: 'POST',
          body: JSON.stringify({ message: content }),
          signal: AbortSignal.timeout(30000),
        })

        if (!response.ok) {
          throw response
        }

        return response.json()
      })

      // Update message status to sent
      setMessages((prev) =>
        prev.map((m) =>
          m.content === content && m.status === 'sending' ? { ...m, status: 'sent' } : m
        )
      )
      setPendingMessage(null)
    } catch (err) {
      // Update message status to failed
      setMessages((prev) =>
        prev.map((m) =>
          m.content === content && m.status === 'sending' ? { ...m, status: 'failed' } : m
        )
      )
    }
  }

  return (
    <div className="flex flex-col h-full">
      <MessageList messages={messages} />

      {error && errorType && (
        <RetryBanner
          errorType={errorType}
          attemptNumber={attemptNumber}
          maxAttempts={maxAttempts}
          retryIn={retryIn}
          onCancel={() => {
            reset()
            setPendingMessage(null)
          }}
          onRetryNow={() => {
            if (pendingMessage) {
              sendMessage(pendingMessage)
            }
          }}
