## Strategy 4: Response Caching

Many queries are repeated. "What are your business hours?" gets asked 500 times per day. Why call
the API 500 times for the same answer?

> **Production Note:** The in-memory cache shown below is for illustration. In production, use Redis
> or another distributed cache to handle scale and avoid memory issues.

```typescript
import { createHash } from 'crypto'
import OpenAI from 'openai'

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY })

// Wrapper function for OpenAI chat completions
async function callOpenAI(message: string, systemPrompt: string): Promise<string> {
  const response = await openai.chat.completions.create({
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: message },
    ],
  })
  return response.choices[0].message.content || ''
}

interface CacheEntry {
  response: string
  timestamp: number
  ttl: number
}

const cache = new Map<string, CacheEntry>()

function getCacheKey(message: string, systemPrompt: string): string {
  // Normalize the message
  const normalized = message.toLowerCase().trim()
  return createHash('sha256').update(`${systemPrompt}:${normalized}`).digest('hex')
}

async function getCachedOrFetch(
  message: string,
  systemPrompt: string,
  ttlSeconds = 3600
): Promise<{ response: string; cached: boolean }> {
  const key = getCacheKey(message, systemPrompt)

  // Check cache
  const cached = cache.get(key)
  if (cached && Date.now() - cached.timestamp < cached.ttl * 1000) {
    return { response: cached.response, cached: true }
  }

  // Cache miss - call API
  // callOpenAI is your wrapper around openai.chat.completions.create()
  const response = await callOpenAI(message, systemPrompt)

  // Store in cache
  cache.set(key, {
    response,
    timestamp: Date.now(),
    ttl: ttlSeconds,
  })

  return { response, cached: false }
}
```

For semantic matching (catching variations like "what are your hours" vs "when are you open"), we
added embedding-based similarity:

```typescript
async function findSimilarCached(message: string, threshold = 0.92): Promise<string | null> {
  const embedding = await embed(message)

  for (const [key, entry] of cache.entries()) {
    const cachedEmbedding = await embed(entry.normalizedQuery)
    const similarity = cosineSimilarity(embedding, cachedEmbedding)

    if (similarity > threshold && Date.now() - entry.timestamp < entry.ttl * 1000) {
      return entry.response
    }
  }

  return null
}
```

**Results:**

- 23% cache hit rate
- Zero cost for cached responses
- Savings: **$900/month**

