  cacheHitRate: `${((stats.cachedTokens / (stats.cachedTokens + stats.uncachedTokens)) * 100).toFixed(1)}%`,
  estimatedMonthlySavings: `$${(stats.estimatedSavings * 4).toFixed(2)}`,
})
