### Hybrid Search

Combine vector similarity with keyword matching:

```typescript
import OpenAI from 'openai'

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY })

// Embedding function
async function embed(text: string): Promise<number[]> {
  const response = await openai.embeddings.create({
    model: 'text-embedding-3-small',
    input: text,
  })
  return response.data[0].embedding
}

// Chunk type for retrieval
interface Chunk {
  id: string
  content: string
  metadata?: Record<string, unknown>
}

interface SearchResult {
  id: string
  chunk: Chunk
  score: number
}

interface RetrievalResult {
  chunk: Chunk
  score: number
}

interface RerankResult {
  chunk: Chunk
  score: number
}

// Vector store abstraction - implement with Pinecone, Weaviate, Qdrant, pgvector, etc.
const vectorStore = {
  search: async (embedding: number[], k: number): Promise<SearchResult[]> => {
    // Example: await pinecone.query({ vector: embedding, topK: k })
    // Returns array of { id, chunk, score }
    return []
  },
  upsert: async (
    chunks: Array<{ id: string; embedding: number[]; metadata: Record<string, unknown> }>
  ) => {
    // Store chunks in vector database
  },
}

// Keyword index abstraction - implement with Elasticsearch, Meilisearch, or in-memory BM25
const keywordIndex = {
  search: async (query: string, k: number): Promise<SearchResult[]> => {
    // Example: await elasticsearch.search({ query, size: k })
    // Returns array of { id, chunk, score }
    return []
  },
  index: async (chunks: Chunk[]) => {
    // Index chunks for keyword search
  },
}

// Cosine similarity for vector comparison
function cosineSimilarity(a: number[], b: number[]): number {
  const dotProduct = a.reduce((sum, val, i) => sum + val * b[i], 0)
  const magnitudeA = Math.sqrt(a.reduce((sum, val) => sum + val * val, 0))
  const magnitudeB = Math.sqrt(b.reduce((sum, val) => sum + val * val, 0))
  return dotProduct / (magnitudeA * magnitudeB)
}

interface RetrievalConfig {
  vectorWeight: number // Weight for semantic similarity
  keywordWeight: number // Weight for BM25/keyword match
  initialK: number // How many to retrieve initially
  finalK: number // How many to return after reranking
  minScore: number // Minimum relevance score
}

async function hybridRetrieve(
  query: string,
  config: RetrievalConfig = {
    vectorWeight: 0.7,
    keywordWeight: 0.3,
    initialK: 20,
    finalK: 5,
    minScore: 0.6,
  }
): Promise<RetrievalResult[]> {
  // Vector search
  const queryEmbedding = await embed(query)
  const vectorResults = await vectorStore.search(queryEmbedding, config.initialK)

  // Keyword search (BM25)
  const keywordResults = await keywordIndex.search(query, config.initialK)

  // Combine scores
  const combined = new Map<string, { chunk: Chunk; score: number }>()

  for (const result of vectorResults) {
    combined.set(result.id, {
      chunk: result.chunk,
      score: result.score * config.vectorWeight,
    })
  }

  for (const result of keywordResults) {
    const existing = combined.get(result.id)
    if (existing) {
      existing.score += result.score * config.keywordWeight
    } else {
      combined.set(result.id, {
        chunk: result.chunk,
        score: result.score * config.keywordWeight,
      })
    }
  }

  // Sort by combined score
  const sorted = Array.from(combined.values())
    .sort((a, b) => b.score - a.score)
    .slice(0, config.initialK)

  // Rerank for final selection
  const reranked = await rerank(
    query,
    sorted.map((s) => s.chunk)
  )

  // Filter by minimum score
  return reranked.filter((r) => r.score >= config.minScore).slice(0, config.finalK)
}
```

### The Reranking Secret

Initial retrieval is cheap and fast but imprecise. Reranking is expensive but accurate. Do both:

```typescript
// npm install cohere-ai
import { CohereClient } from 'cohere-ai'

// Initialize Cohere client for reranking
const cohereClient = new CohereClient({
  token: process.env.COHERE_API_KEY || '',
})

// Chunk and result types (defined earlier, repeated for clarity)
interface Chunk {
  id: string
  content: string
  metadata?: Record<string, unknown>
}

interface RerankResult {
  chunk: Chunk
  score: number
}

async function rerank(query: string, chunks: Chunk[]): Promise<RerankResult[]> {
  // Use a cross-encoder model for precise ranking
  // Options: Cohere Rerank, BGE Reranker, custom model

  const response = await cohereClient.rerank({
    model: 'rerank-english-v3.0',
    query: query,
    documents: chunks.map((c) => c.content),
    top_n: chunks.length,
  })

  return response.results.map((result, i) => ({
    chunk: chunks[result.index],
    score: result.relevance_score,
  }))
}
```

### Know When to Say "I Don't Know"

The most important RAG feature: admitting ignorance.

```typescript
// Generate answer using retrieved context
async function generateAnswer(query: string, context: string): Promise<string> {
  const response = await openai.chat.completions.create({
    model: 'gpt-4o',
    messages: [
      {
        role: 'system',
        content: `Answer the question based only on the provided context. If the context doesn't contain enough information, say so.

Context:
${context}`,
      },
      { role: 'user', content: query },
    ],
    max_tokens: 500,
  })
  return response.choices[0].message.content || ''
}

// Format retrieved chunks for LLM context
function formatContext(results: RetrievalResult[]): string {
  return results
    .map((r, i) => `[Source ${i + 1}] (relevance: ${r.score.toFixed(2)})\n${r.chunk.content}`)
    .join('\n\n---\n\n')
}

async function queryWithConfidence(
  query: string
): Promise<{ answer: string; confidence: 'high' | 'medium' | 'low' | 'none' }> {
  const results = await hybridRetrieve(query)

  // No relevant results
  if (results.length === 0) {
    return {
      answer: "I don't have information about that in my knowledge base.",
      confidence: 'none',
    }
  }

  // Low relevance scores
  const avgScore = results.reduce((sum, r) => sum + r.score, 0) / results.length
  if (avgScore < 0.5) {
    return {
      answer:
        "I found some potentially relevant information, but I'm not confident it answers your question. Here's what I found: ...",
      confidence: 'low',
    }
  }

  // Good results - generate answer
  const context = results.map((r) => r.chunk.content).join('\n\n')
  const answer = await generateAnswer(query, context)

  return {
    answer,
    confidence: avgScore > 0.8 ? 'high' : 'medium',
  }
}
```

