### Validate Arguments

Don't trust the AI's arguments blindly:

```typescript
// npm install zod
import { z } from 'zod'

const searchProductsSchema = z.object({
  query: z.string().min(1).max(200),
  category: z.enum(['electronics', 'clothing', 'home', 'sports', 'books']).optional(),
  maxPrice: z.number().positive().max(10000).optional(),
  inStock: z.boolean().optional(),
})

const addToCartSchema = z.object({
  productId: z.string().min(1),
  quantity: z.number().int().min(1).max(10).optional(),
})

const getOrderStatusSchema = z.object({
  orderId: z.string().min(1),
})

async function validateAndExecute<T>(
  functionName: string,
  args: unknown,
  handler: (args: T) => Promise<unknown>
): Promise<unknown> {
  const schemas: Record<string, z.ZodSchema> = {
    search_products: searchProductsSchema,
    add_to_cart: addToCartSchema,
    get_order_status: getOrderStatusSchema,
  }

  const schema = schemas[functionName]
  if (!schema) {
    throw new Error(`No schema for function: ${functionName}`)
  }

  const validated = schema.parse(args)
  return handler(validated)
}
```

### Require Confirmation for Sensitive Actions

Some actions shouldn't execute automatically:

```typescript
interface AgentConfig {
  requireConfirmation: string[] // Functions that need user OK
  maxIterations: number
  timeout: number
}

interface PendingAction {
  function: string
  arguments: Record<string, unknown>
  description: string
}

// UI helper - implement based on your UI framework
async function showConfirmDialog(message: string): Promise<boolean> {
  // For React: use a modal state + promise
  // For simple cases: return window.confirm(message)
  return window.confirm(message)
}

// Human-readable action description
function describeAction(functionName: string, args: string): string {
  const parsed = JSON.parse(args)
  const descriptions: Record<string, (args: Record<string, unknown>) => string> = {
    add_to_cart: (a) => `add ${a.quantity || 1} of product ${a.productId} to your cart`,
    submit_order: () => 'submit your order',
    delete_item: (a) => `delete item ${a.itemId}`,
  }
  return descriptions[functionName]?.(parsed) || `perform ${functionName}`
}

async function runAgentWithConfirmation(
  userMessage: string,
  config: AgentConfig,
  onConfirmationNeeded: (action: PendingAction) => Promise<boolean>
): Promise<string> {
  // ... agent loop ...

  for (const toolCall of assistantMessage.tool_calls) {
    const functionName = toolCall.function.name

    // Check if confirmation needed
    if (config.requireConfirmation.includes(functionName)) {
      const confirmed = await onConfirmationNeeded({
        function: functionName,
        arguments: JSON.parse(toolCall.function.arguments),
        description: describeAction(functionName, toolCall.function.arguments),
      })

      if (!confirmed) {
        messages.push({
          role: 'tool',
          tool_call_id: toolCall.id,
          content: JSON.stringify({ error: 'User cancelled this action' }),
        })
        continue
      }
    }

    // Execute...
  }
}

// Usage
const response = await runAgentWithConfirmation(
  userMessage,
  {
    requireConfirmation: ['add_to_cart', 'submit_order', 'delete_item'],
    maxIterations: 10,
    timeout: 30000,
  },
  async (action) => {
    // Show confirmation UI to user
    return await showConfirmDialog(`The assistant wants to ${action.description}. Allow?`)
  }
)
```

### Handle Tool Failures

Tools fail. APIs go down. Handle it gracefully:

```typescript
async function executeToolSafely(
  toolCall: ToolCall,
  handler: ToolHandler
): Promise<{ success: boolean; result?: unknown; error?: string }> {
  try {
    const args = JSON.parse(toolCall.function.arguments)
    const result = await Promise.race([
      handler(args),
      new Promise((_, reject) => setTimeout(() => reject(new Error('Tool timeout')), 10000)),
    ])
    return { success: true, result }
  } catch (error) {
    console.error(`Tool ${toolCall.function.name} failed:`, error)
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error',
    }
  }
}

// In the agent loop
const toolResult = await executeToolSafely(toolCall, handler)

messages.push({
  role: 'tool',
  tool_call_id: toolCall.id,
  content: JSON.stringify(
    toolResult.success ? toolResult.result : { error: `Tool failed: ${toolResult.error}` }
  ),
})
```

The AI will see the error and can inform the user or try an alternative approach.

