```tsx
import {
  ChatWindow,
  ThemeProvider,
  themes,
  useChat,
  useStreamingSSE,
  useTokenTracker,
  useErrorRecovery,
} from '@clarity-chat/react'

function ProductionChat() {
  // All the complexity, handled
  const chat = useChat({
    initialMessages: [],
    maxTokens: 4096,
  })

  const streaming = useStreamingSSE({
    url: '/api/chat/stream',
    reconnect: true,
  })

  const tokens = useTokenTracker({
    maxTokens: 4096,
    warningThreshold: 0.8,
  })

  const errorRecovery = useErrorRecovery({
    maxRetries: 3,
    backoffStrategy: 'exponential',
  })

  return (
    <ThemeProvider theme={themes.ocean}>
      <ChatWindow
        messages={chat.messages}
        onSendMessage={chat.sendMessage}
        streaming={streaming}
        tokens={tokens}
        errorRecovery={errorRecovery}
        // Everything else handled automatically:
        // ✅ Retry logic
        // ✅ Token tracking
        // ✅ Realistic typing
        // ✅ Accessibility
        // ✅ Mobile optimization
        // ✅ Keyboard shortcuts
        // ✅ Error messages
        // ✅ Loading states
        // ✅ Theme switching
      />
    </ThemeProvider>
  )
}
```

