### Options

```tsx
interface UseAssistantOptions {
  /** API endpoint URL */
  api?: string

  /** Assistant ID */
  assistantId?: string

  /** Thread ID (for multi-turn conversations) */
  threadId?: string

  /** Initial messages */
  initialMessages?: CoreMessage[]

  /** Additional body data */
  body?: Record<string, any>

  /** Custom headers */
  headers?: Record<string, string>

  /** Fetch credentials mode */
  credentials?: RequestCredentials

  /** Custom fetch implementation */
  fetch?: typeof fetch

  /** Maximum number of steps */
  maxSteps?: number

  /** Callback when response is received */
  onResponse?: (response: Response) => void | Promise<void>

  /** Callback when assistant finishes */
  onFinish?: (message: CoreMessage) => void | Promise<void>

  /** Callback on error */
  onError?: (error: Error) => void

  /** Callback when tool is invoked */
  onToolCall?: (toolCall: ToolInvocation) => void

  /** Enable streaming (default: true) */
  stream?: boolean

  /** Experimental features */
  experimental?: {
    [key: string]: any
  }
}
```

### Return Value

```tsx
interface UseAssistantReturn {
  /** Current status */
  status: 'idle' | 'in_progress' | 'awaiting_message'

  /** Current messages */
  messages: CoreMessage[]

  /** Set messages directly */
  setMessages: React.Dispatch<React.SetStateAction<CoreMessage[]>>

  /** Submit a message to the assistant */
  submitMessage: (
    message: string | CoreMessage,
    options?: { data?: Record<string, any> }
  ) => Promise<void>

  /** Handle form submission */
  handleSubmit: (
    event?: React.FormEvent<HTMLFormElement>,
    options?: { data?: Record<string, any> }
  ) => void

  /** Input value */
  input: string

  /** Set input value */
  setInput: React.Dispatch<React.SetStateAction<string>>

  /** Whether currently loading */
  isLoading: boolean

  /** Current error */
  error: Error | undefined

  /** Current assistant message being streamed */
  data: CoreMessage | undefined

  /** Current tool invocations */
  toolInvocations: ToolInvocation[]

  /** Stop the current assistant */
  stop: () => void

  /** Abort controller for current request */
  abort: () => void

  /** Append a message manually */
  append: (message: CoreMessage) => void
}
```

### Example

```tsx
function Assistant() {
  const {
    status,
    messages,
    submitMessage,
    input,
    setInput,
    isLoading,
    toolInvocations,
  } = useAssistant({
    api: '/api/assistant',
    assistantId: 'my-assistant',
    onToolCall: (toolCall) => {
      console.log('Tool called:', toolCall.toolName)
    },
  })

  return (
    <div>
      <div>Status: {status}</div>
      {messages.map((m) => (
        <div key={m.id}>{messageToText(m)}</div>
      ))}
      {toolInvocations.map((inv) => (
        <div key={inv.toolCallId}>Tool: {inv.toolName}</div>
      ))}
      <form onSubmit={(e) => {
        e.preventDefault()
        submitMessage(input)
        setInput('')
      }}>
        <input value={input} onChange={(e) => setInput(e.target.value)} />
        <button type="submit" disabled={isLoading}>Send</button>
      </form>
    </div>
  )
}
```

