  modelName: 'custom-model',
  maxTokens: 4096,
  inputCostPerToken: 0.00002,
  outputCostPerToken: 0.00004,
  warningThreshold: 0.7,
  onWarning: () => {
    console.log('Approaching token limit')
  },
  onCritical: () => {
    showPruneDialog()
  },
})

