  const { suggestPruning, clear } = useTokenTracker({
    modelName: 'gpt-4',
  })

  return (
    <div>
      {suggestPruning && (
        <button onClick={clear}>
          Prune old messages to free up space
        </button>
      )}
    </div>
  )
}
