  const [messages, setMessages] = useState<string[]>([])

  const voice = useVoiceInput({
    continuous: true,
    interimResults: true,
    onTranscript: (text, isFinal) => {
      if (isFinal) {
        setMessages(prev => [...prev, text])
      }
    }
  })

  return <div>...</div>
}

