## Hook Composition Example

Combine multiple hooks for complex functionality:

```typescript
function AdvancedChat() {
  const { messages, sendMessage, isLoading } = useChat()
  const { tokenCount, isNearLimit } = useTokenCount({ messages })
  const { isOnline, reconnect } = useNetworkStatus()
  const { context, addContext } = useContextManager()
  const { files, uploadFiles } = useFileUpload()

  const handleSend = async (content: string) => {
    if (!isOnline) {
      await reconnect()
    }

    if (isNearLimit) {
      alert('Token limit approaching!')
      return
    }

    await sendMessage(content)
  }

  return (
    <ChatWindow
      messages={messages}
      isLoading={isLoading}
      onSendMessage={handleSend}
      onFileUpload={uploadFiles}
    />
  )
}
```

### ModelAdapter

The base interface that all adapters implement:

```typescript
interface ModelAdapter {
  /** Adapter name */
  name: string

  /** Send a chat completion request */
  chat(messages: ChatMessage[], config: ModelConfig): Promise<ChatMessage>

  /** Stream chat completion tokens */
  stream(messages: ChatMessage[], config: ModelConfig): AsyncGenerator<StreamChunk>

  /** Estimate cost based on token usage */
  estimateCost(usage: TokenUsage, model: string): number
}
```

### ModelConfig

Configuration for model requests:

```typescript
interface ModelConfig {
  /** Provider name */
  provider: 'openai' | 'anthropic' | 'google' | 'custom'

  /** Model ID */
  model: string

  /** API key (optional, can use env vars) */
  apiKey?: string

  /** Custom API base URL */
  baseURL?: string

  /** Sampling temperature (0-2) */
  temperature?: number

  /** Maximum tokens to generate */
  maxTokens?: number

  /** Top-p sampling parameter */
  topP?: number

  /** Frequency penalty (-2 to 2) */
  frequencyPenalty?: number

  /** Presence penalty (-2 to 2) */
  presencePenalty?: number

  /** Stop sequences */
  stop?: string[]

  /** Streaming callbacks */
  streamOptions?: StreamOptions

  /** AbortSignal for cancellation */
  signal?: AbortSignal
}
```

### StreamOptions

Callbacks for streaming events:

```typescript
interface StreamOptions {
  /** Called for each token */
  onToken?: (token: string) => void

  /** Called for each tool invocation */
  onToolCall?: (tool: ToolCall) => void

  /** Called for each thinking step */
  onThinking?: (step: string) => void

  /** Called for each citation */
  onCitation?: (citation: Citation) => void

  /** Called when streaming starts */
  onStart?: () => void

  /** Called when streaming completes */
  onComplete?: (usage: TokenUsage) => void

  /** Called on error */
  onError?: (error: Error) => void
}
```

### StreamChunk

Union type for all streaming events:

```typescript
type StreamChunk = 
  | TokenChunk
  | ToolCallChunk
  | ThinkingChunk
  | CitationChunk
  | DoneChunk
  | ErrorChunk

interface TokenChunk {
  type: 'token'
  content: string
}

interface ToolCallChunk {
  type: 'tool_call'
  toolCall: ToolCall
}

interface ThinkingChunk {
  type: 'thinking'
  content: string
}

interface CitationChunk {
  type: 'citation'
  citation: Citation
}

interface DoneChunk {
  type: 'done'
  usage: TokenUsage
}

interface ErrorChunk {
  type: 'error'
  error: Error
}
```

